    79      const __m128i perm = _mm_shuffle_epi8(in, sh);
    80      const __m128i ascii = _mm_and_si128(perm, _mm_set1_epi16(0x7f));
    81      const __m128i highbyte = _mm_and_si128(perm, _mm_set1_epi16(0x1f00));
    82      const __m128i composed = _mm_or_si128(ascii, _mm_srli_epi16(highbyte, 2));
    83      _mm_storeu_si128(reinterpret_cast<__m128i *>(utf32_output), _mm_cvtepu16_epi32(composed));
    84      _mm_storeu_si128(reinterpret_cast<__m128i *>(utf32_output+4), _mm_cvtepu16_epi32(_mm_srli_si128(composed,8)));
    85      utf32_output += 6; // We wrote 12 bytes, 6 code points.
    86    } else if (idx < 145) {
    87      // FOUR (4) input code-code units
    88      const __m128i sh =
    89          _mm_loadu_si128((const __m128i *)tables::utf8_to_utf16::shufutf8[idx]);
    90      const __m128i perm = _mm_shuffle_epi8(in, sh);
    91      const __m128i ascii =
    92          _mm_and_si128(perm, _mm_set1_epi32(0x7f)); // 7 or 6 bits
    93      const __m128i middlebyte =
    94          _mm_and_si128(perm, _mm_set1_epi32(0x3f00)); // 5 or 6 bits
    95      const __m128i middlebyte_shifted = _mm_srli_epi32(middlebyte, 2);
    96      const __m128i highbyte =
    97          _mm_and_si128(perm, _mm_set1_epi32(0x0f0000)); // 4 bits
    98      const __m128i highbyte_shifted = _mm_srli_epi32(highbyte, 4);
    99      const __m128i composed =
   100          _mm_or_si128(_mm_or_si128(ascii, middlebyte_shifted), highbyte_shifted);
   101      _mm_storeu_si128((__m128i *)utf32_output, composed);
   102      utf32_output += 4;
   103    } else if (idx < 209) {
   104      // TWO (2) input code-code units
   105      const __m128i sh =
   106          _mm_loadu_si128((const __m128i *)tables::utf8_to_utf16::shufutf8[idx]);
   107      const __m128i perm = _mm_shuffle_epi8(in, sh);
   108      const __m128i ascii = _mm_and_si128(perm, _mm_set1_epi32(0x7f));
   109      const __m128i middlebyte = _mm_and_si128(perm, _mm_set1_epi32(0x3f00));
   110      const __m128i middlebyte_shifted = _mm_srli_epi32(middlebyte, 2);
   111      __m128i middlehighbyte = _mm_and_si128(perm, _mm_set1_epi32(0x3f0000));
   112      // correct for spurious high bit
   113      const __m128i correct =
   114          _mm_srli_epi32(_mm_and_si128(perm, _mm_set1_epi32(0x400000)), 1);
   115      middlehighbyte = _mm_xor_si128(correct, middlehighbyte);
   116      const __m128i middlehighbyte_shifted = _mm_srli_epi32(middlehighbyte, 4);
   117      const __m128i highbyte = _mm_and_si128(perm, _mm_set1_epi32(0x07000000));
   118      const __m128i highbyte_shifted = _mm_srli_epi32(highbyte, 6);
   119      const __m128i composed =
   120          _mm_or_si128(_mm_or_si128(ascii, middlebyte_shifted),
   121                       _mm_or_si128(highbyte_shifted, middlehighbyte_shifted));
   122      _mm_storeu_si128((__m128i *)utf32_output, composed);
   123      utf32_output += 3;
   124    } else {
   125      // here we know that there is an error but we do not handle errors
   126    }
   127    return consumed;
   128  }
